function analysisRows(intent,parsed){var rows=phaseRows().filter(visibleClient),today=localDate(0),week=isoAdd(today,7);rows=rows.map(function(r){r._status=statusFor(r);return r});if(intent==='inactive_customers')rows=rows.filter(function(r){return r._status.elapsed!=null&&r._status.elapsed>=parsed.days});else if(intent==='due_customers')rows=rows.filter(function(r){return r._status.key==='due'});else if(intent==='overdue_customers')rows=rows.filter(function(r){return r._status.key==='overdue'});else if(intent==='risk_customers'||intent==='risk_candidates')rows=rows.filter(function(r){return r._status.key==='risk'});else if(intent==='attention_customers')rows=rows.filter(function(r){return ['due','overdue','risk'].includes(r._status.key)});else if(intent==='due_this_week')rows=rows.filter(function(r){return r.expected_next_visit_date>=today&&r.expected_next_visit_date<=week});else if(intent==='regular_customers')rows=rows.filter(function(r){return r._status.key==='regular'&&r.average_visit_days}).sort(function(a,b){return a.average_visit_days-b.average_visit_days});else if(intent==='lapsed_customers')rows=rows.filter(function(r){return ['overdue','risk'].includes(r._status.key)&&Number(r.distinct_visit_days||0)>=3});return rows.slice(0,parsed.limit||50)}
