  var value='';if(parsed.intent==='client_last_visit')value=row.last_visit_date?'Son geliş: '+friendlyDate(row.last_visit_date):'Kayıt bulunamadı.';else if(parsed.intent==='client_absence_days')value=status.elapsed==null?'Bunu hesaplamak için yeterli ziyaret geçmişi yok.':status.elapsed+' gündür gelmiyor.';else if(parsed.intent==='client_visit_count')value=Number(row.visit_count||0)+' kez geldi.';else if(parsed.intent==='client_average')value=row.average_visit_days?'Ortalama '+row.average_visit_days+' günde bir geliyor.':'Bunu hesaplamak için yeterli ziyaret geçmişi yok.';else if(parsed.intent==='client_due')value=status.key==='due'?'Evet, gelme zamanı geldi.':'Durum: '+status.label+'.';else if(parsed.intent==='client_risk')value=status.key==='risk'?'Evet, kaybedilme riski taşıyor.':'Hayır. Durum: '+status.label+'.';else if(parsed.intent==='client_next_visit')value=row.expected_next_visit_date?'Tahmini sonraki geliş: '+friendlyDate(row.expected_next_visit_date):'Bunu hesaplamak için yeterli ziyaret geçmişi yok.';else if(parsed.intent==='client_notes')value=client.note||row.note||'Kayıtlı müşteri notu yok.';else if(parsed.intent==='client_top_service')value=row.preferred_service_name?'En sık hizmet: '+row.preferred_service_name:'Bunu hesaplamak için yeterli ziyaret geçmişi yok.';else if(parsed.intent==='client_preferred_employee'){var employee=profileById(row.preferred_employee_id);value=employee?'Genellikle '+employee.full_name+' çalışanına geliyor.':'Bunu hesaplamak için yeterli ziyaret geçmişi yok.'}
