function nearbySlots(date,employeeId,time){var rows=(cache.get('day:'+date)||{}).data||[],profile=profileById(employeeId),target=Number(time.slice(0,2))*60+Number(time.slice(3));return slotGroups(date,rows,[profile],null).flatMap(function(g){var values=[];for(var m=g.start;m<g.end;m+=30)values.push(m);return values}).sort(function(a,b){return Math.abs(a-target)-Math.abs(b-target)}).slice(0,3).map(clock)}
