async function prepareMutation(parsed){var client=await resolveClient(parsed);if(client==='ambiguous')return;if(!client){notice('Kayıt bulunamadı. Müşteri adını biraz daha açık yazın.');return}if(parsed.intent==='create_appointment'){if(!parsed.date||!parsed.time){notice(parsed.time?'Randevu tarihini net anlayamadım. “yarın” veya “28 Ağustos” gibi söyleyin.':'Randevu saatini net anlayamadım. “16:00” veya “dört buçuk” gibi söyleyin.');return}confirmation({type:'create',client:client,date:parsed.date,time:parsed.time,employee:parsed.employee||(!isManager()?profileById(currentUser.id):null),summary:friendlyDate(parsed.date)+' · '+parsed.time+' için randevu formu açılacak.'});return}
  var rows=await futureAppointments(client.id);if(parsed.appointmentId)rows=rows.filter(function(a){return String(a.id)===String(parsed.appointmentId)});if(!rows.length){notice('Değiştirilebilecek gelecek randevu bulunamadı.');return}if(rows.length>1&&!parsed.appointmentId){appointmentChoice(rows,parsed);return}var item=rows[0];if(!canManageOwnAppointment(item)){notice('Bu randevuyu değiştirme yetkiniz yok.');return}var date=parsed.date||appointmentDate(item),time=parsed.time||item.time,employee=parsed.intent==='transfer_appointment'?parsed.employee:null;if(parsed.intent==='transfer_appointment'&&!employee){notice('Hedef çalışanı açıkça yazın.');return}var employeeId=employee?employee.id:item.employeeId,duration=Number(item.duration||30);await dayAppointments(date);if(parsed.intent!=='cancel_appointment'&&appointmentConflictFor(date,time,duration,employeeId,item.id)){var alternatives=nearbySlots(date,employeeId,time);notice((employee?employee.full_name:item.staff)+' '+time+' saatinde dolu.'+(alternatives.length?' Yakın boş saatler: '+alternatives.join(', '):''));return}var summary=parsed.intent==='cancel_appointment'?friendlyDate(appointmentDate(item))+' · '+item.time+' randevusu iptal edilecek.':friendlyDate(appointmentDate(item))+' '+item.time+' → '+friendlyDate(date)+' '+time+(employee?' · Çalışan: '+employee.full_name:'');confirmation({type:parsed.intent,item:item,appointment:item,date:date,time:time,employeeId:employeeId,employeeName:employee?employee.full_name:item.staff,summary:summary})}
